#!/bin/zsh
# Shared worktree-materialization helpers for worktree-ticket.sh (mwt) and
# worktree-generic.sh (wt) so the two never drift. Sourced, not executed.

# .husky/_/husky.sh is gitignored and generated by `prepare` on yarn install. A fresh worktree never runs yarn,
# so the tracked hooks (which source that file) break every commit until husky is installed here.
function wt_install_hooks() {
    local DIR="$1"
    [[ -d "$DIR/.husky" && ! -f "$DIR/.husky/_/husky.sh" ]] || return 0
    echo "Installing git hooks (husky)…"
    if [[ -x "$DIR/node_modules/.bin/husky" ]]; then
        (cd "$DIR" && ./node_modules/.bin/husky install)
    else
        (cd "$DIR" && npx husky install)
    fi
}

# Claude Code reads .claude/settings.local.json from the project root only and it is gitignored, so a worktree
# would miss repo-specific settings (e.g. the autoMode environment kept out of the public dotfile repo).
# Symlinked, not copied, so permissions granted in any worktree land in one file.
function wt_link_claude_local() {
    local SRC="$1/.claude/settings.local.json" DEST="$2/.claude/settings.local.json"
    [[ -f "$SRC" && ! -e "$DEST" ]] || return 0
    mkdir -p "$2/.claude" && ln -s "$SRC" "$DEST"
}

# APFS copy-on-write clone of node_modules: ~0 disk, isolated per worktree (a yarn install in one never
# mutates another's deps). clonefile(2) on the *directory* clones the whole hierarchy in one kernel call
# (~5s for 214k files); `cp -c -R` clones the same blocks but walks the tree one copyfile(2) per entry (~4 min).
# Destination must not exist, which holds right after `git worktree add` since node_modules is untracked.
function wt_clone_node_modules() {
    local SRC="$1" DEST="$2"
    [[ -d "$SRC/node_modules" ]] || return 0
    echo "Cloning node_modules (APFS copy-on-write)…"
    if ! /usr/bin/python3 -c '
import ctypes, sys
libc = ctypes.CDLL("/usr/lib/libSystem.dylib", use_errno=True)
libc.clonefile.argtypes = [ctypes.c_char_p, ctypes.c_char_p, ctypes.c_int]
sys.exit(0 if libc.clonefile(sys.argv[1].encode(), sys.argv[2].encode(), 0) == 0 else 1)
' "$SRC/node_modules" "$DEST/node_modules" 2>/dev/null; then
        echo "clonefile unavailable, falling back to cp -c -R (slower)…"
        rm -rf "$DEST/node_modules"
        cp -c -R "$SRC/node_modules" "$DEST/node_modules"
    fi
}

function wt_repo_name() {
    print -r -- "${1:t}"
}

# Default branch for a remote: its HEAD symref first, then main/master.
function wt_default_base_branch() {
    local REMOTE="${1:-origin}"
    local REF
    REF=$(git symbolic-ref -q "refs/remotes/$REMOTE/HEAD" 2>/dev/null) && {
        print -r -- "${REF#refs/remotes/$REMOTE/}"
        return 0
    }
    local CANDIDATE
    for CANDIDATE in main master; do
        git show-ref --verify --quiet "refs/remotes/$REMOTE/$CANDIDATE" && {
            print -r -- "$CANDIDATE"
            return 0
        }
    done
    return 1
}
